local _, ns = ...
local L = ns.locales.ruRU
L.helpTour = "Экскурсия"
L.helpTourTip = "Пошаговый показ рынков и кнопок поверх окна."
L.helpWiki = "Справочник рынков"
L.helpWikiTip = "Что считает каждый рынок, откуда цены, как и когда их обновлять."
L.wikiTitle = "Справочник рынков"
L.wikiHeadAbout = "О чём рынок"
L.wikiHeadPrices = "Откуда цены"
L.wikiHeadMath = "Как считается"
L.wikiHeadRefresh = "Как обновлять"
L.wikiHeadKeep = "Что хранится и сколько"
L.wikiHeadBest = "Когда что лучше"
L.wikiKeepScans = "Каждый поиск хранится около %d дн., дальше самые старые уходят."
L.wikiKeepFull = "Последняя полная картина рынка твоего реалма и фракции хранится всегда."
L.wikiKeepChart = "Окно \"Рынок\" помнит цены предмета до %d дн."
L.wikiKeyBargainSoft = "Не проверенные дольше срока свежести."
L.wikiKeyBargainHard = "Все предметы группы."
L.wikiKeyBuy = "\"Поиск\" — всегда заново."
L.wikiAbout_processing = "Что выгоднее: продать как есть или переработать и продать результат.\nРаспыл — экипировка в пыль, эссенции и осколки; \"Цель распыла\" — какие вещи дают нужный материал.\nПросеивание и Измельчение — руда в камни, травы в пигменты, по 5 штук за операцию.\nСубстанции и стихии — малые и великие 3:1, стихии и частицы 10:1."
L.wikiPrices_processing = "Цены материалов и сырья — из твоих поисков кнопками экрана.\nВещи для распыла ищутся категорией экипировки целиком.\nВыход — средний по шансам: одна операция бывает и хуже, и лучше."
L.wikiRefresh_processing = "Кнопки \"Дополнить\" — внизу экрана; \"Вещи\" в Распыле ищутся заново при любом клике."
L.wikiKeep_processing = "Твои цены материалов распыла поиск не заменяет."
L.wikiBest_processing = "Много дешёвой экипировки — Распыл по экипировке.\nНужен конкретный материал — \"Цель распыла\" или Просеивание, и сравни с покупкой.\nМалые и великие субстанции стоят не в пропорции 3:1 — Субстанции и стихии."
L.wikiAbout_professions = "Выбери профессию в меню, затем режим.\nКрафт — рецепты по марже, справа Партия на заход.\nСырьё — руда, травы, шкуры и рыба: цена и выгода переработки.\nПрокачка — маршрут навыка с корзиной реагентов (Наложение чар и Алхимия).\nРецепты у NPC — формулы торговцев на перепродажу."
L.wikiPrices_professions = "Товары и реагенты — из твоих поисков по рецептам.\nРеагенты, которые продаёт торговец, идут по его цене и на аукционе не ищутся."
L.wikiRefresh_professions = "\"Дополнить профессию\" собирает цены всех рецептов и вложенных реагентов за одно нажатие.\nОдну строку обновляет её значок."
L.wikiKeep_professions = "Избранные рецепты закреплены первыми, пока не уберёшь их из списка."
L.wikiBest_professions = "Ищешь, что скрафтить на продажу — Крафт: сверху самые выгодные.\nЕсть навык сбора — Сырьё: продать как есть или переработать.\nКачаешь навык — Прокачка, корзину докупи в \"Купить\"."
L.wikiAbout_materials = "От материала к применению: продать как есть, скрафтить, переработать или обменять.\n\"Все\" — материалы всех каталогов, \"В сумках\" — то, что лежит в сумках персонажа.\nСправа — что сделать с материалом и форма \"Выставить\"."
L.wikiPrices_materials = "Рынок за штуку — из твоих поисков; цена торговца рыночной не считается.\nСебестоимость в сумках — из Учёта, когда известны цены всех партий."
L.wikiRefresh_materials = "\"Дополнить применения\" — в \"Все\", \"Дополнить сумки\" — в \"В сумках\"."
L.wikiBest_materials = "Разбираешь сумки — \"В сумках\": сразу видно, что продать и почём.\nРешаешь, куда пустить материал, — \"Все\" и блок \"Что сделать\"."
L.wikiAbout_bargain = "Список наблюдения: эпики рейдов, маунты и питомцы, редкие рецепты и реагенты, плюс твои предметы.\nИщет лоты дешевле обычной цены, после которых перепродажа остаётся в плюсе.\nЛот ниже цены торговца отмечен: его выгодно купить и сразу продать NPC."
L.wikiPrices_bargain = "Лоты — из поисков \"Дополнить\" по имени предмета.\nОбычная цена — по первому, что есть: твоя, медиана проверок за %d дн. (нужно хотя бы %d) или рынок текущих лотов."
L.wikiRefresh_bargain = "За нажатие — не больше %d поисков, сначала давно не проверенные; остаток уйдёт следующим нажатием."
L.wikiKeep_bargain = "Твой список, скрытые и своя цена предмета хранятся, пока их не уберёшь."
L.wikiBest_bargain = "Есть свободное золото — \"Выгодные\" после \"Дополнить\".\nСвои товары для перепродажи — в \"Мой список\" полем \"Добавить\"."
L.wikiAbout_seasonal = "Товары праздников: задания, достижения и праздничный крафт.\nСверху праздник; даты — из календаря игры.\n\"Есть у NPC\" — товар продаёт торговец, можно без аукциона."
L.wikiPrices_seasonal = "Цены — из \"Дополнить праздник\" и значков строк.\nЦена в таблице — аукционная даже у товаров торговца: для сравнения."
L.wikiRefresh_seasonal = "\"Дополнить праздник\" — справа в шапке праздника."
L.wikiBest_seasonal = "Даты подскажут, когда товар понадобится: проверь цены заранее.\n\"Купить на аукционе\" в панели откроет поиск с количеством на одно применение."
L.wikiAbout_npc = "NPC-трейдинг — купить у торговца за золото или обмен и продать на аукционе.\nВалюта — что купить за эмблемы, честь, знаки и Ледяной шар.\nРецепты у NPC — формулы торговцев на перепродажу.\nТолько передаваемые товары и торговцы твоей фракции или нейтральные."
L.wikiPrices_npc = "Цена у NPC — из справочника торговцев аддона, цена аукциона — из твоих поисков.\nОбмен стоит суммы цен аукциона за то, чем платишь."
L.wikiRefresh_npc = "\"Дополнить\" внизу — товары открытого сегмента; \"Аукцион\" ищет выбранный товар в \"Купить\"."
L.wikiBest_npc = "Копится валюта — \"Валюта\": видно выручку за единицу.\nЕсть золото и мало времени — NPC-трейдинг: купил у торговца и выставил."
L.wikiAbout_collections = "Избранные рецепты и отслеживаемые предметы в одном месте.\nДобавь предмет по имени, номеру или ссылке здесь или звездой в панели предмета.\nИзбранное закрепляется первым в списке профессии."
L.wikiPrices_collections = "Цены — из \"Дополнить список\" и значков строк; цена и время наблюдения видны отдельно."
L.wikiRefresh_collections = "\"Дополнить список\" обновляет предметы открытого списка."
L.wikiKeep_collections = "Списки хранятся, пока не уберёшь предмет."
L.wikiBest_collections = "Следишь за десятком товаров — держи их здесь и обновляй одним нажатием."
L.wikiAbout_hidden = "Товары и группы, убранные из рабочих списков всех экранов.\nФильтры по профессии и категории рецепта; \"Вернуть все\" — по текущему фильтру."
L.wikiPrices_hidden = "Цены скрытых не ищутся и не мешают выбору лучшего."
L.wikiRefresh_hidden = "Обновлять здесь нечего: верни товар, и его цены снова будут искаться."
L.wikiKeep_hidden = "Скрытие хранится, пока не вернёшь товар."
L.wikiBest_hidden = "Скрывай то, что не продаётся или не нужно: поисков станет меньше."
L.wikiAbout_accounting = "Цепочки \"вход — переработка — выход — продажа\": распыл, просеивание, измельчение, крафт и перепродажа.\nВещи, Материалы, Журнал, Анализ и Прогноз — разные срезы тех же записей.\n\"Новая партия\" начинает новый счёт, старое не удаляется."
L.wikiPrices_accounting = "Записи пишутся сами: покупки, почта, переработка, крафт, выставление и деньги за продажу.\nОстаток оценивается по текущим ценам аукциона после комиссии."
L.wikiRefresh_accounting = "Учёт сам ничего не ищет; \"Дополнить прогноз\" — остатки партии и товары рецептов прогноза."
L.wikiKeep_accounting = "Журнал покупок, продаж и распыла хранится целиком и не удаляется.\n\"Всё в учёт\" записывает любой выкуп, не только товары каталогов."
L.wikiBest_accounting = "Начинай партию перед новым заходом, чтобы видеть его итог отдельно."
L.wikiAbout_buy = "Найди предмет по имени и купи нужное количество или всё, что дешевле твоей цены.\n\"Сколько нужно\" — сколько купить, \"Дешевле, за шт.\" — до какой цены за штуку.\nВыкуп — только кликом; перед ним лот находится снова и цена проверяется."
L.wikiPrices_buy = "Только свежий поиск этого предмета: каждый \"Поиск\" читает лоты заново.\nПанель справа: цены сейчас и медиана 7 дней из прошлых поисков."
L.wikiRefresh_buy = "Новые лоты появятся только после нового поиска."
L.wikiKeep_buy = "Недавние — до %d предметов за %d дн., с последним количеством и прошлой покупкой."
L.wikiBest_buy = "Значок покупки в строках других экранов открывает здесь поиск этого предмета.\n\"До прошлой цены\" ставит лимит по прошлой покупке."
L.wikiAbout_sell = "Что из сумок стоит продать и почём, выставление пачками.\n\"Мои лоты\" — твои лоты против чужих и снятие."
L.wikiPrices_sell = "Цены — из \"Дополнить сумки\" и \"Дополнить мои лоты\".\nСписок своих лотов аукцион присылает сам: при открытии и после выставления."
L.wikiRefresh_sell = "Кнопка дополнения — у правого края таблицы, своя на каждый вид."
L.wikiBest_sell = "Перед выставлением обнови цены сумок, чтобы не продать дешевле рынка."
